<script setup>
import {computed, nextTick, onMounted, onBeforeUnmount, reactive, ref, watch} from 'vue'
import axios, {downloadImage, downloadJson,getImagePreview} from './imageMetadataClient'
import {fieldInfo} from './metadataFields'
import L from 'leaflet'

const props=defineProps({confirmAction:Function})
const emit=defineEmits(['notify'])
const notify=(message,type='info')=>emit('notify',message,type)
const images=ref([]), selected=ref([]), active=ref(null), busy=ref(false), loading=ref(false), capabilities=ref(null)
const uploadInput=ref(), tab=ref('common'), query=ref(''), group=ref(''), drafts=reactive({}), deleted=ref([])
const failures=ref([]), progress=ref(''), tagQuery=ref(''), tagResults=ref([]), newTag=ref(''), newValue=ref(''),tagPickerOpen=ref(false)
const gps=reactive({enabled:false,latitude:'',longitude:'',altitude:''})
const addedLists=new Set()
const customPngFields=new Set()
const ruleType=ref('attitude'),ruleTarget=ref('PNG:CalculatedValue'),ruleExpression=ref('${GPS:GPSAltitude}'),ruleBusy=ref(false)
const ruleChecking=ref(false),ruleCheck=ref({eligible:[],errors:[]})
let ruleCheckTimer=0,ruleCheckSerial=0
const previewFailed=ref(false)
const inspectorBody=ref()
watch([()=>active.value?.id,tab],async()=>{await nextTick();if(inspectorBody.value)inspectorBody.value.scrollTop=0})
const previews=reactive({}),previewErrors=reactive({})
let previewSerial=0
const mapElement=ref(); let map,marker,searchTimer,detailSerial=0,searchSerial=0
const accept='.jpg,.jpeg,.heic,.heif,.png,.webp,.tif,.tiff,.bmp,.gif,.avif'
const common=[
  {key:'ExifIFD:DateTimeOriginal',label:'拍摄时间',placeholder:'2026:09:07 12:30:00'},
  {key:'ExifIFD:OffsetTimeOriginal',label:'拍摄时区',placeholder:'+08:00'},
  {key:'IFD0:Artist',label:'作者',placeholder:'摄影师 / 作者'},
  {key:'IFD0:Copyright',label:'版权',placeholder:'版权声明'},
  {key:'IFD0:ImageDescription',label:'描述',placeholder:'这张照片的说明'},
  {key:'IFD0:Make',label:'相机品牌',placeholder:'如 Apple、Canon'},
  {key:'IFD0:Model',label:'相机型号',placeholder:'相机或手机型号'},
  {key:'ExifIFD:LensModel',label:'镜头型号',placeholder:'镜头名称'},
  {key:'IFD0:XResolution',label:'水平分辨率',placeholder:'如 300'},
  {key:'IFD0:YResolution',label:'垂直分辨率',placeholder:'如 300'},
  {key:'IFD0:ResolutionUnit',label:'分辨率单位',options:[['1','无单位'],['2','英寸（DPI）'],['3','厘米']]},
  {key:'IFD0:Orientation',label:'方向',options:[['1','正常'],['2','水平镜像'],['3','旋转 180°'],['4','垂直镜像'],['5','镜像并转置'],['6','顺时针 90°'],['7','镜像并横置'],['8','逆时针 90°']]},
]
const fields=computed(()=>active.value?.fields||[])
const groups=computed(()=>[...new Set(fields.value.map(f=>f.group))].sort())
const visibleFields=computed(()=>fields.value.filter(f=>(!group.value||f.group===group.value)&&`${f.key} ${f.label} ${text(f.value)}`.toLowerCase().includes(query.value.toLowerCase())))
const pending=computed(()=>Object.keys(drafts).length+deleted.value.length+(gps.enabled?1:0))
const allSelected=computed(()=>images.value.length>0&&selected.value.length===images.value.length)
const source=(item)=>/^(HEIC|HEIF)$/.test(item.format)?(previews[item.id]?.revision===item.revision?previews[item.id].url:undefined):item.preview_url
const helpFor=key=>{const [group,name]=key.split(':');return fieldInfo(name,group,true).description.replace(' 按原始字段值编辑，保存时会进行回读校验。','')}
const newFieldHelp=computed(()=>tagResults.value.find(f=>f.key===newTag.value)?.description||'选择字段后查看说明。')
const selectedTag=computed(()=>tagResults.value.find(f=>f.key===newTag.value))
const newTagExists=computed(()=>fields.value.some(field=>field.key===newTag.value))
const customTagCandidate=computed(()=>{const value=tagQuery.value.trim(),name=value.replace(/^PNG:/i,'');return active.value?.format==='PNG'&&/^[A-Za-z][A-Za-z0-9 _-]{0,78}$/.test(name)?`PNG:${name}`:''})
watch(images,items=>{
  ++previewSerial
  for(const id of Object.keys(previews)){if(!items.some(item=>item.id===id)){delete previews[id];delete previewErrors[id]}}
})
async function ensurePreview(item){
  if(!item||!/^(HEIC|HEIF)$/.test(item.format)||previews[item.id]?.revision===item.revision)return
  const serial=++previewSerial;delete previewErrors[item.id]
  try{const url=await getImagePreview(item.id);if(serial===previewSerial)previews[item.id]={revision:item.revision,url}}
  catch(error){if(serial===previewSerial)previewErrors[item.id]=error.message}
}
const text=value=>Array.isArray(value)?value.join('\n'):typeof value==='object'?JSON.stringify(value,null,2):String(value??'')
const bytes=value=>value>=1048576?`${(value/1048576).toFixed(1)} MB`:`${Math.max(1,Math.round(value/1024))} KB`
const valueFor=key=>Object.hasOwn(drafts,key)?drafts[key]:text(fields.value.find(f=>f.key===key)?.value)
const hasPosition=computed(()=>Number.isFinite(Number(active.value?.latitude))&&active.value?.latitude!=null&&Number.isFinite(Number(active.value?.longitude))&&active.value?.longitude!=null)

function clearDrafts(){Object.keys(drafts).forEach(k=>delete drafts[k]);deleted.value=[];gps.enabled=false;addedLists.clear();customPngFields.clear();newTag.value='';newValue.value='';tagQuery.value='';tagPickerOpen.value=false}
function change(key,value){drafts[key]=value;deleted.value=deleted.value.filter(k=>k!==key)}
function toggleDelete(key){if(deleted.value.includes(key))deleted.value=deleted.value.filter(k=>k!==key);else{deleted.value.push(key);delete drafts[key]}}
function select(id){selected.value=selected.value.includes(id)?selected.value.filter(x=>x!==id):[...selected.value,id]}
async function confirm(message){return props.confirmAction?props.confirmAction(message,'确认操作'):window.confirm(message)}
async function activate(item,force=false){
  if(!force&&active.value?.id===item.id)return
  if(!force&&pending.value&&!await confirm('切换图片将放弃尚未保存的修改，是否继续？'))return
  const serial=++detailSerial;loading.value=true
  try{const {data}=await axios.get(`/api/image-metadata/images/${item.id}`);if(serial!==detailSerial)return;active.value=data;previewFailed.value=false;clearDrafts();gps.latitude=data.latitude??'';gps.longitude=data.longitude??'';gps.altitude=fields.value.find(f=>f.key==='Composite:GPSAltitude')?.value??fields.value.find(f=>f.key==='GPS:GPSAltitude')?.value??'';group.value='';await ensurePreview(data)}
  catch(e){notify(e.response?.data?.detail||e.message,'error')}finally{if(serial===detailSerial)loading.value=false}
}
async function refresh(){const {data}=await axios.get('/api/image-metadata/images');images.value=data;selected.value=selected.value.filter(id=>data.some(item=>item.id===id))}
async function upload(event){
  const files=[...event.target.files];event.target.value='';if(!files.length)return
  if(files.length>100)return notify('每次最多上传 100 张图片。','error')
  if(files.some(f=>f.size>100*1048576)||files.reduce((s,f)=>s+f.size,0)>1024*1048576)return notify('单张最多 100MB，每次上传最多 1GB。','error')
  if(pending.value&&!await confirm('上传新图片将放弃尚未保存的修改，是否继续？'))return
  busy.value=true;failures.value=[];progress.value='正在本地读取图片…'
  try{const body=new FormData();files.forEach(file=>body.append('files',file));const {data}=await axios.post('/api/image-metadata/images',body,{onUploadProgress:e=>{progress.value=e.total?`正在本地读取第 ${e.loaded+1}/${e.total} 张图片…`:'正在读取…'}});failures.value=data.errors;await refresh();selected.value=data.images.map(i=>i.id);if(data.images.length)await activate(data.images[0],true);notify(`已载入 ${data.images.length} 张图片${data.errors.length?`，${data.errors.length} 张失败`:''}`,data.errors.length?'info':'success')}
  catch(e){notify(e.response?.data?.detail||e.message,'error')}finally{busy.value=false;progress.value=''}
}
async function run(payload,description,confirmation,ids=[...selected.value]){
  if(!ids.length)return notify('请先勾选图片。')
  if(confirmation&&!await confirm(`${confirmation}（${ids.length} 张图片）`))return
  busy.value=true;progress.value=description;failures.value=[]
  try{const names=Object.fromEntries(images.value.map(i=>[i.id,i.name]));const {data}=await axios.post('/api/image-metadata/batch',{ids,...payload});failures.value=data.errors.map(e=>({...e,name:names[e.id]}));const activeFailed=data.errors.some(e=>e.id===active.value?.id);await refresh();if(active.value&&images.value.some(i=>i.id===active.value.id)){if(!activeFailed&&ids.includes(active.value.id))await activate(active.value,true)}else{++detailSerial;active.value=null;clearDrafts();if(images.value.length){selected.value=selected.value.length?selected.value:[images.value[0].id];await activate(images.value[0],true)}}notify(data.errors.length?`${description}：${data.errors.length} 张失败，请查看详情`:payload.action==='delete'?'已删除图片、原图及编辑副本。':'操作完成，已重新读取文件中的元数据。',data.errors.length?'info':'success')}
  catch(e){notify(e.response?.data?.detail||e.message,'error')}finally{busy.value=false;progress.value=''}
}
function save(){
  const updates={},custom_updates={};for(const [key,value] of Object.entries(drafts)){const field=fields.value.find(f=>f.key===key),target=customPngFields.has(key)?custom_updates:updates;target[key]=field?.list||addedLists.has(key)?value.split('\n').filter(Boolean):value}
  const payload={updates,custom_updates,deletes:deleted.value}
  if(gps.enabled){if(gps.latitude===''||gps.longitude==='')return notify('请同时填写纬度和经度。','error');payload.gps={latitude:gps.latitude,longitude:gps.longitude,altitude:gps.altitude}}
  run(payload,'保存修改')
}
async function exportSelected(){if(!selected.value.length)return;busy.value=true;progress.value='正在打包图片…';try{const {data}=await axios.post('/api/image-metadata/export',{ids:selected.value},{responseType:'blob'});const url=URL.createObjectURL(data),a=document.createElement('a');a.href=url;a.download='图片与元数据.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){notify('下载失败，请重试。','error')}finally{busy.value=false;progress.value=''}}
async function exportMetadata(){if(!selected.value.length)return;busy.value=true;progress.value=`正在导出 ${selected.value.length} 张图片的元数据…`;try{const {data}=await axios.post('/api/image-metadata/metadata-export',{ids:selected.value},{responseType:'blob'});const url=URL.createObjectURL(data),a=document.createElement('a');a.href=url;a.download='已选图片元数据JSON.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify(`已导出 ${selected.value.length} 份元数据 JSON。`,'success')}catch(e){notify(e.message||'元数据导出失败，请重试。','error')}finally{busy.value=false;progress.value=''}}
watch(tagQuery,()=>{if(newTag.value)return;clearTimeout(searchTimer);const serial=++searchSerial;searchTimer=setTimeout(async()=>{try{const {data}=await axios.get('/api/image-metadata/tags',{params:{q:tagQuery.value}});if(serial===searchSerial)tagResults.value=data}catch(e){notify(e.response?.data?.detail||e.message,'error')}},250)})
function addField(){if(!newTag.value)return;const updating=newTagExists.value;if(tagResults.value.find(f=>f.key===newTag.value)?.list)addedLists.add(newTag.value);change(newTag.value,newValue.value);newTag.value='';newValue.value='';tagQuery.value='';tagPickerOpen.value=false;notify(updating?'已有字段已加入更新。':'新字段已加入待保存修改。')}
function searchTagInput(){newTag.value='';tagPickerOpen.value=true}
function chooseTag(field){newTag.value=field.key;tagQuery.value=`${field.label} · ${field.key}`;tagPickerOpen.value=false}
function commitTagInput(){const value=tagQuery.value.trim().toLowerCase(),field=tagResults.value.find(item=>item.key.toLowerCase()===value||item.label.toLowerCase()===value)||tagResults.value[0];if(field)chooseTag(field);else if(customTagCandidate.value)createCustomTag()}
function createCustomTag(){if(!customTagCandidate.value)return;newTag.value=customTagCandidate.value;customPngFields.add(newTag.value);tagQuery.value=newTag.value;tagPickerOpen.value=false}
function closeTagPicker(){setTimeout(()=>tagPickerOpen.value=false,120)}
const currentRule=()=>ruleType.value==='attitude'?{type:'attitude'}:{type:'custom',target:ruleTarget.value.trim(),expression:ruleExpression.value.trim()}
async function runRuleCheck(){const serial=++ruleCheckSerial;if(!selected.value.length){ruleCheck.value={eligible:[],errors:[]};return ruleCheck.value}ruleChecking.value=true;try{const {data}=await axios.post('/api/image-metadata/rules/check',{ids:[...selected.value],rule:currentRule()});if(serial===ruleCheckSerial)ruleCheck.value=data;return data}catch(error){const data={eligible:[],errors:[{error:error.message}]};if(serial===ruleCheckSerial)ruleCheck.value=data;return data}finally{if(serial===ruleCheckSerial)ruleChecking.value=false}}
function scheduleRuleCheck(){clearTimeout(ruleCheckTimer);++ruleCheckSerial;if(tab.value!=='rules'){ruleChecking.value=false;return}ruleChecking.value=true;ruleCheckTimer=setTimeout(runRuleCheck,260)}
async function applyRule(){if(!selected.value.length)return notify('请先选择图片。','error');const checked=await runRuleCheck();if(checked.eligible.length!==selected.value.length)return notify('存在缺少前置字段或不支持写入的图片，无法执行规则。','error');ruleBusy.value=true;failures.value=[];try{const names=Object.fromEntries(images.value.map(item=>[item.id,item.name])),{data}=await axios.post('/api/image-metadata/rules/apply',{ids:selected.value,rule:currentRule()});failures.value=data.errors.map(error=>({...error,name:names[error.id]}));await refresh();if(active.value)await activate(images.value.find(item=>item.id===active.value.id)||images.value[0],true);notify(data.errors.length?`${data.errors.length} 张图片计算失败，请查看详情。`:'计算结果已写入并完成回读校验。',data.errors.length?'info':'success')}catch(error){notify(error.message||'规则执行失败','error')}finally{ruleBusy.value=false}}
watch([tab,()=>selected.value.map(id=>`${id}:${images.value.find(item=>item.id===id)?.revision||0}`).join('|'),ruleType,ruleTarget,ruleExpression],scheduleRuleCheck)
async function renderMap(){await nextTick();if(!hasPosition.value||!mapElement.value){map?.remove();map=null;return}if(!map){map=L.map(mapElement.value,{scrollWheelZoom:false}).setView([0,0],3);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map)}const point=[Number(active.value.latitude),Number(active.value.longitude)];if(marker)marker.remove();marker=L.marker(point).addTo(map);map.setView(point,12);map.invalidateSize()}
watch([active,tab],renderMap)
onMounted(async()=>{try{capabilities.value=(await axios.get('/api/image-metadata/capabilities')).data;await refresh();if(images.value.length){selected.value=[images.value[0].id];await activate(images.value[0],true)}}catch(e){notify(e.response?.data?.detail||e.message,'error')}})
onBeforeUnmount(()=>{++previewSerial;clearTimeout(searchTimer);clearTimeout(ruleCheckTimer);map?.remove()})
</script>

<template>
  <section class="metadata-page">
    <header class="metadata-header"><div><span class="eyebrow">IMAGE METADATA STUDIO</span><h1>图片元数据</h1><p>查看照片背后的信息，精确编辑位置、时间、设备与版权。</p></div><span class="metadata-badge">EXIF · GPS · IPTC · XMP</span></header>
    <div v-if="capabilities&&!capabilities.available" class="metadata-alert">{{capabilities.error}}</div>
    <div class="metadata-toolbar"><div><input ref="uploadInput" class="metadata-file-input" type="file" multiple :accept="accept" @change="upload"><button class="md-primary" :disabled="busy||capabilities?.available===false" @click="uploadInput.click()">＋ 上传图片</button><span>单张 / 多张 · HEIC、JPG、PNG、WEBP、TIFF 等</span></div><div><small>{{selected.length}} / {{images.length}} 张已选</small><button :disabled="busy||!selected.length" @click="exportMetadata">导出元数据 JSON</button><button :disabled="busy||!selected.length" @click="exportSelected">下载选中图片</button><button class="md-danger" :disabled="busy||!selected.length" @click="run({action:'delete'},'删除图片','删除选中图片及其原图、编辑副本和预览缓存？')">删除选中</button></div></div>
    <div v-if="busy" class="metadata-progress" role="status">{{progress}}</div>
    <div v-if="failures.length" class="metadata-alert"><b>部分文件未完成操作</b><div v-for="(error,index) in failures" :key="index">{{error.name||error.id}}：{{error.error}}</div></div>
    <div v-if="!images.length" class="metadata-empty"><div class="metadata-empty-icon">⌘</div><h2>让每张图片的信息清晰可见</h2><p>上传后可预览图片、浏览全部可识别字段，并对多张图片应用同一组修改。</p><div class="metadata-features"><span>地理位置与海拔</span><span>拍摄时间与设备</span><span>版权与关键词</span><span>像素尺寸与分辨率</span></div><button class="md-primary" :disabled="busy||capabilities?.available===false" @click="uploadInput.click()">选择图片</button><small>每次最多 100 张，单张最多 100MB。图片仅在浏览器内处理，可恢复原图，不上传服务器。</small></div>
    <div v-else class="metadata-workspace" :class="{working:busy}">
      <aside class="metadata-library"><div class="metadata-library-head"><label><input type="checkbox" :checked="allSelected" :disabled="busy" @change="selected=allSelected?[]:images.map(i=>i.id)">全选</label><b>图片库</b></div><div class="metadata-files"><div v-for="item in images" :key="item.id" class="metadata-file" :class="{active:active?.id===item.id}"><input type="checkbox" :checked="selected.includes(item.id)" :aria-label="`选择 ${item.name}`" :disabled="busy" @change="select(item.id)"><button :disabled="busy" @click="activate(item)"><img v-if="source(item)" :src="source(item)" alt="" loading="lazy"><span v-else class="metadata-thumb-placeholder">HEIC</span><span><b :title="item.name">{{item.name}}</b><small>{{item.format}} · {{bytes(item.size)}}</small></span></button><button class="metadata-delete-one" :disabled="busy" :aria-label="`删除 ${item.name}`" :title="`删除 ${item.name}`" @click.stop="run({action:'delete'},'删除图片',`删除 ${item.name} 及其原图、编辑副本和预览缓存？`,[item.id])">×</button></div></div></aside>
      <section class="metadata-preview"><div class="metadata-preview-heading"><div><b>{{active?.name||'选择图片'}}</b><small>{{active?.format}} <template v-if="active?.width"> · {{active.width}} × {{active.height}} px</template> · {{bytes(active?.size||0)}}</small></div><div v-if="active"><button @click="downloadImage(active.id)">下载图片</button><button @click="downloadJson(active.id)">元数据 JSON</button></div></div><div class="metadata-canvas"><img v-if="active && source(active)" :src="source(active)" :alt="active.name" @error="previewFailed=true" @load="previewFailed=false" :style="{visibility:previewFailed?'hidden':'visible'}"><span v-if="loading">读取元数据中…</span><span v-else-if="active && previewErrors[active.id]">{{previewErrors[active.id]}}</span><span v-else-if="active && !source(active)">正在本地解码 HEIC 预览…</span><span v-else-if="previewFailed">浏览器不支持此格式预览，仍可编辑和下载元数据</span></div><div class="metadata-location"><div><b>拍摄位置</b><small>{{hasPosition?`${active.latitude}, ${active.longitude}`:'此图片未记录 GPS 坐标'}}</small></div><div v-if="hasPosition" ref="mapElement" class="metadata-map"></div></div><p class="metadata-caption">图片保存在当前浏览器，不上传服务器；元数据写入不重新编码像素。HEIC 在浏览器内解码为预览图，下载仍保留原始格式；不改动原图。</p></section>
      <section class="metadata-inspector"><div class="metadata-tabs"><button :class="{active:tab==='common'}" @click="tab='common'">常用信息</button><button :class="{active:tab==='all'}" @click="tab='all'">全部字段 <small>{{fields.length}}</small></button><button :class="{active:tab==='add'}" @click="tab='add'">字段编辑</button><button :class="{active:tab==='rules'}" @click="tab='rules'">计算规则</button></div>
        <div ref="inspectorBody" class="metadata-inspector-body">
          <template v-if="tab==='common'"><div class="metadata-section-title"><b>基本信息</b><small>只保存有修改的字段</small></div><div class="metadata-form-grid"><label v-for="field in common" :key="field.key"><span class="metadata-field-label">{{field.label}}</span><select v-if="field.options" :value="valueFor(field.key)" @change="change(field.key,$event.target.value)"><option value="">未设置</option><option v-for="option in field.options" :key="option[0]" :value="option[0]">{{option[1]}}</option></select><input v-else :value="valueFor(field.key)" :placeholder="field.placeholder" @input="change(field.key,$event.target.value)"><small class="metadata-field-help">{{helpFor(field.key)}}</small></label></div><div class="metadata-section-title"><label><input v-model="gps.enabled" type="checkbox">更新 GPS 位置</label><button class="md-text-danger" :disabled="!selected.length||busy" @click="run({clear_gps:true},'移除 GPS','移除选中图片的 GPS 坐标和海拔？')">移除 GPS</button></div><div class="metadata-form-grid"><label>纬度<input v-model="gps.latitude" :disabled="!gps.enabled" type="number" step="any" min="-90" max="90" placeholder="北纬为正，南纬为负"></label><label>经度<input v-model="gps.longitude" :disabled="!gps.enabled" type="number" step="any" min="-180" max="180" placeholder="东经为正，西经为负"></label><label>海拔（米）<input v-model="gps.altitude" :disabled="!gps.enabled" type="number" step="any" placeholder="海平面以下为负"></label></div><small class="metadata-help">分辨率是打印密度；像素宽高、编码和数据偏移属于图片结构，只读保护。仅日期没有时区时保留原值，避免误改照片的拍摄时间。</small></template>
          <template v-else-if="tab==='all'"><div class="metadata-filter"><input v-model="query" type="search" placeholder="搜索字段、内容…"><select v-model="group"><option value="">全部分组</option><option v-for="name in groups" :key="name">{{name}}</option></select></div><small class="metadata-help">读取所有可识别字段。文件结构、二进制块和计算字段只读；列表字段每行一项。数字字段使用原始数值。</small><div class="metadata-field-list"><div v-for="field in visibleFields" :key="field.key" class="metadata-field" :class="{removed:deleted.includes(field.key)}"><div><b>{{field.label}}</b><small>{{field.key}}</small><button v-if="field.writable" :title="deleted.includes(field.key)?'取消删除':'标记删除此字段'" @click="toggleDelete(field.key)">{{deleted.includes(field.key)?'撤销':'删除'}}</button><span v-else>只读</span></div><textarea v-if="field.writable" :value="valueFor(field.key)" rows="2" :disabled="deleted.includes(field.key)" @input="change(field.key,$event.target.value)"></textarea><pre v-else>{{text(field.value)}}</pre><p class="metadata-field-help">{{field.description}}</p></div><p v-if="!visibleFields.length">没有匹配的字段。</p></div></template>
          <template v-else-if="tab==='add'"><div class="metadata-section-title"><b>新增或更新元数据字段</b></div><p class="metadata-help">输入中文名称、字段名或分组并直接选择。已有字段会更新；PNG 可创建自定义文本字段。</p><label>字段<div class="metadata-tag-picker" @focusout="closeTagPicker"><div class="metadata-tag-combobox" :class="{open:tagPickerOpen}"><input v-model="tagQuery" placeholder="例如：版权、Artist、PNG:ProjectId" autocomplete="off" @input="searchTagInput" @focus="tagPickerOpen=true" @keydown.enter.prevent="commitTagInput"><i @click="tagPickerOpen=!tagPickerOpen">⌄</i></div><div v-if="tagPickerOpen" class="metadata-tag-options"><button v-for="field in tagResults" :key="field.key" type="button" :class="{selected:newTag===field.key}" @mousedown.prevent @click="chooseTag(field)"><span><b>{{field.label}}</b><small>{{field.key}}</small></span><em>{{fields.some(item=>item.key===field.key)?'更新':'新增'}}</em></button><button v-if="customTagCandidate&&!tagResults.some(field=>field.key===customTagCandidate)" type="button" class="create-custom-tag" @mousedown.prevent @click="createCustomTag"><span><b>创建自定义 PNG 字段</b><small>{{customTagCandidate}}</small></span><em>新增</em></button><p v-if="!tagResults.length&&!customTagCandidate">没有匹配的可安全写入字段；自定义字段仅支持 PNG。</p></div></div></label><div v-if="newTag" class="metadata-tag-selection"><span :class="newTagExists?'update':'create'">{{newTagExists?'更新已有字段':'新增字段'}}</span><b>{{selectedTag?.label||newTag}}</b><small>{{newTag}}</small></div><p class="metadata-field-help">{{newFieldHelp}}</p><label>字段内容<textarea v-model="newValue" rows="5" placeholder="填写字段值（列表每行一项，数字和枚举使用原始值）"></textarea></label><button :disabled="!newTag" @click="addField">{{newTagExists?'加入更新':'加入新增'}}</button></template>
          <template v-else><div class="metadata-section-title"><b>基于现有元数据计算并写入</b></div><div class="metadata-rule-switch"><button :class="{active:ruleType==='attitude'}" @click="ruleType='attitude'">内置规则</button><button :class="{active:ruleType==='custom'}" @click="ruleType='custom'">自定义规则</button></div><section v-if="ruleType==='attitude'" class="metadata-rule-card"><b>计算三维姿态</b><p>读取 Apple:AccelerationVector 计算 Pitch、Roll；读取 GPSImgDirection 写入 Yaw。</p><small>前置字段：Apple:AccelerationVector、GPS:GPSImgDirection、GPS:GPSImgDirectionRef；仅支持 PNG 无损写入。</small></section><section v-else class="metadata-custom-rule"><label>结果字段<input v-model="ruleTarget" placeholder="PNG:CalculatedValue"></label><label>计算公式<textarea v-model="ruleExpression" rows="4" placeholder="例如：${GPS:GPSAltitude} * 3.28084"></textarea></label><small>公式中的 ${分组:字段} 均为前置字段；支持 + - * /、abs、sqrt、hypot、atan2、sin、cos、tan、round、min、max 和 PI。</small></section><div class="metadata-rule-readiness" :class="{ready:selected.length&&ruleCheck.eligible.length===selected.length,error:ruleCheck.errors.length}"><b>{{ruleChecking?`正在增量检查 ${selected.length} 张图片…`:ruleCheck.eligible.length===selected.length&&selected.length?'满足使用条件':`不可使用 · ${ruleCheck.eligible.length}/${selected.length} 张满足条件`}}</b><ul v-if="ruleCheck.errors.length"><li v-for="(item,index) in ruleCheck.errors.slice(0,4)" :key="index">{{images.find(image=>image.id===item.id)?.name||'图片'}}：{{item.error}}</li></ul><small v-if="ruleCheck.errors.length>4">另有 {{ruleCheck.errors.length-4}} 张不满足条件</small></div><button class="md-primary metadata-rule-run" :disabled="ruleBusy||ruleChecking||!selected.length||ruleCheck.eligible.length!==selected.length" @click="applyRule">{{ruleBusy?'正在计算并校验…':`应用到 ${selected.length} 张已选图片`}}</button></template>
          <div v-if="pending" class="metadata-drafts"><b>{{pending}} 项待保存修改</b><div v-for="(value,key) in drafts" :key="key"><span>{{key}}</span><button @click="delete drafts[key]">撤销</button></div><div v-for="key in deleted" :key="key"><span>删除 {{key}}</span></div><button @click="clearDrafts">放弃所有修改</button></div>
        </div><div class="metadata-save"><button class="md-primary" :disabled="busy||loading||!pending||!selected.length" @click="save">{{busy?'正在处理…':`保存到 ${selected.length} 张已选图片`}}</button><div><button :disabled="busy||!selected.length" @click="run({restore:true},'恢复原图','放弃选中图片的全部编辑并恢复上传时的原始文件？')">恢复原图</button><button class="md-text-danger" :disabled="busy||!selected.length" @click="run({clear_all:true},'清除元数据','清除所有可安全编辑的字段？结构、色彩配置及受保护的厂商信息仍会保留，不等于彻底匿名化。')">清除可编辑字段</button></div></div>
      </section>
    </div>
  </section>
</template>

